sp_widget.client_script:
api.controller=function($location) {

    var c = this;


    // =====================================================
    // INITIAL STATE
    // =====================================================

    c.loading = true;
    c.error = '';
    c.application = null;


    // =====================================================
    // GET APPLICATION SYS_ID
    // =====================================================

    c.getApplicationId = function() {

        var params = $location.search();

        if (params.sys_id) {
            return params.sys_id;
        }

        if (params.sysid) {
            return params.sysid;
        }

        return '';
    };


    // =====================================================
    // LOAD APPLICATION
    // =====================================================

    c.loadApplication = function() {

        c.loading = true;
        c.error = '';


        var applicationId =
            c.getApplicationId();


        if (!applicationId) {

            c.loading = false;

            c.error =
                'Application record was not specified.';

            return;
        }


        /*
         * Send Application sys_id to Server Script.
         */

        c.data.action = 'load_application';

        c.data.applicationId =
            applicationId;


        c.server.update().then(

            function(response) {

                c.loading = false;


                if (
                    !response ||
                    !response.data
                ) {

                    c.error =
                        'Unable to load application details.';

                    return;
                }


                if (response.data.error) {

                    c.error =
                        response.data.error;

                    return;
                }


                if (
                    !response.data.application
                ) {

                    c.error =
                        'Application record could not be found.';

                    return;
                }


                c.application =
                    response.data.application;

            },

            function() {

                c.loading = false;

                c.error =
                    'Unable to load application details.';

            }
        );

    };


    // =====================================================
    // BACK TO MY APPLICATIONS
    // =====================================================

    c.goBack = function() {

        $location.url(
            '?id=my_applications'
        );

    };


    // =====================================================
    // NORMALIZE
    // =====================================================

    c.normalize = function(value) {

        if (
            value === null ||
            value === undefined
        ) {
            return '';
        }

        return String(value)
            .trim()
            .toLowerCase();

    };


    // =====================================================
    // STATUS CLASS
    // =====================================================

    c.getStatusClass = function(status) {

        var value =
            c.normalize(status);


        if (
            value === 'shortlisted'
        ) {
            return 'shortlisted';
        }


        if (
            value === 'interview scheduled'
        ) {
            return 'interview';
        }


        if (
            value === 'selected'
        ) {
            return 'selected';
        }


        if (
            value === 'offered'
        ) {
            return 'offered';
        }


        if (
            value === 'rejected'
        ) {
            return 'rejected';
        }


        return 'applied';

    };


    // =====================================================
    // ELIGIBILITY CLASS
    // =====================================================

    c.getEligibilityClass = function(status) {

        var value =
            c.normalize(status);


        if (
            value === 'eligible'
        ) {
            return 'eligible';
        }


        if (
            value === 'not eligible'
        ) {
            return 'not-eligible';
        }


        return '';

    };


    // =====================================================
    // JOURNEY STATUS
    // =====================================================

    c.getJourneyStatus = function() {

        if (!c.application) {
            return 'applied';
        }


        var status =
            c.normalize(
                c.application.status
            );


        if (
            status === 'rejected'
        ) {
            return 'rejected';
        }


        if (
            status === 'offered'
        ) {
            return 'offer';
        }


        if (
            status === 'selected'
        ) {
            return 'selected';
        }


        if (
            status === 'interview scheduled'
        ) {
            return 'interview';
        }


        if (
            status === 'shortlisted'
        ) {
            return 'shortlisted';
        }


        return 'applied';

    };


    // =====================================================
    // JOURNEY CLASS
    // =====================================================

    c.getJourneyClass = function(
        step,
        stepNumber
    ) {

        var current =
            c.getJourneyStatus();


        var currentNumber = 1;


        if (
            current === 'shortlisted'
        ) {

            currentNumber = 2;

        }

        else if (
            current === 'interview'
        ) {

            currentNumber = 3;

        }

        else if (
            current === 'selected'
        ) {

            currentNumber = 4;

        }

        else if (
            current === 'offer'
        ) {

            currentNumber = 5;

        }

        /*
         * Rejected should not make
         * the journey appear completed
         * as an Offer.
         */

        else if (
            current === 'rejected'
        ) {

            currentNumber = 1;

        }


        if (
            stepNumber < currentNumber
        ) {

            return 'journey-completed';

        }


        if (
            stepNumber === currentNumber
        ) {

            if (current === 'rejected') {
                return 'journey-rejected';
            }

            return 'journey-current';

        }


        return 'journey-pending';

    };


    // =====================================================
    // REJECTED CHECK
    // =====================================================

    c.isRejected = function() {

        if (
            !c.application ||
            !c.application.status
        ) {

            return false;

        }


        return (
            c.normalize(
                c.application.status
            ) === 'rejected'
        );

    };


    // =====================================================
    // INITIALIZE
    // =====================================================

    c.$onInit = function() {

        c.loadApplication();

    };


    /*
     * Service Portal compatibility:
     * explicitly call initialization.
     */

    c.$onInit();

}

sp_widget.css:
/* =========================================================
   NEXORA - APPLICATION DETAILS
   PROFESSIONAL SERVICENOW SERVICE PORTAL UI
   NAVY + CORAL THEME
   ========================================================= */


/* =========================================================
   GLOBAL BOX SIZING
   ========================================================= */

.nexora-main.nx-application-page,
.nexora-main.nx-application-page *,
.nexora-main.nx-application-page *::before,
.nexora-main.nx-application-page *::after {
    box-sizing: border-box;
}


/* =========================================================
   MAIN PAGE
   ========================================================= */

.nexora-main.nx-application-page {
    width: 100%;
    min-height: 100vh;

    padding: 42px 48px 60px;

    background: #f4f7fa;

    color: #172b3f;

    font-family:
        "Inter",
        "Segoe UI",
        Arial,
        sans-serif;

    overflow-x: hidden;
}


/* =========================================================
   PAGE CONTENT WIDTH
   ========================================================= */

.nx-application-page .nx-application-details {
    width: 100%;
    max-width: 1450px;
    margin: 0 auto;
}


/* =========================================================
   LOADING
   ========================================================= */

.nx-application-page .nx-app-loading {
    min-height: 420px;

    display: flex;
    flex-direction: column;

    align-items: center;
    justify-content: center;

    gap: 16px;

    color: #617286;

    font-size: 14px;
    font-weight: 600;
}


/* =========================================================
   LOADING SPINNER
   ========================================================= */

.nx-application-page .nx-loading-spinner {
    width: 38px;
    height: 38px;

    border: 3px solid #dfe6ed;
    border-top-color: #ff6b5b;

    border-radius: 50%;

    animation:
        nxApplicationSpin
        0.8s linear infinite;
}


@keyframes nxApplicationSpin {

    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }

}


/* =========================================================
   ERROR STATE
   ========================================================= */

.nx-application-page .nx-app-error {
    max-width: 700px;

    margin: 90px auto;

    padding: 34px;

    background: #ffffff;

    border: 1px solid #e2e8ee;

    border-radius: 16px;

    box-shadow:
        0 10px 30px rgba(23, 43, 63, 0.06);

    display: flex;
    align-items: center;
    gap: 20px;

    position: relative;
}


.nx-application-page .nx-error-icon {
    width: 46px;
    height: 46px;

    flex: 0 0 46px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: #fff1ef;

    color: #d9574b;

    font-size: 21px;
    font-weight: 800;
}


.nx-application-page .nx-error-content {
    flex: 1;
}


.nx-application-page .nx-error-content h3 {
    margin: 0 0 6px;

    color: #172b3f;

    font-size: 20px;
    font-weight: 700;
}


.nx-application-page .nx-error-content p {
    margin: 0;

    color: #6c7c8d;

    font-size: 14px;
    line-height: 1.6;
}


.nx-application-page .nx-error-back-btn {
    margin-left: auto;

    border: 0;

    background: #17334b;
    color: #ffffff;

    border-radius: 8px;

    padding: 11px 17px;

    font-size: 13px;
    font-weight: 700;

    cursor: pointer;

    white-space: nowrap;

    transition:
        background 0.2s ease,
        transform 0.2s ease;
}


.nx-application-page .nx-error-back-btn:hover {
    background: #20435d;
    transform: translateY(-1px);
}


/* =========================================================
   BACK LINK
   ========================================================= */

.nx-application-page .nx-back-link {
    display: inline-flex;

    align-items: center;
    gap: 9px;

    margin: 0 0 24px;

    padding: 0;

    border: 0;
    background: transparent;

    color: #617487;

    font-size: 13px;
    font-weight: 600;

    cursor: pointer;

    transition:
        color 0.2s ease,
        transform 0.2s ease;
}


.nx-application-page .nx-back-link:hover {
    color: #17334b;
    transform: translateX(-3px);
}


.nx-application-page .nx-back-arrow {
    font-size: 18px;
    line-height: 1;
}


/* =========================================================
   APPLICATION HEADER
   ========================================================= */

.nx-application-page .nx-application-header {
    min-height: 145px;

    display: flex;

    align-items: center;
    justify-content: space-between;

    gap: 35px;

    padding: 34px 38px;

    background:
        linear-gradient(
            135deg,
            #17334b 0%,
            #1b3b55 55%,
            #20435d 100%
        );

    border-radius: 18px;

    box-shadow:
        0 14px 32px rgba(23, 51, 75, 0.14);

    position: relative;

    overflow: hidden;
}


/* subtle background detail */

.nx-application-page .nx-application-header::after {
    content: "";

    position: absolute;

    width: 230px;
    height: 230px;

    right: -100px;
    top: -120px;

    border-radius: 50%;

    border: 1px solid rgba(255, 255, 255, 0.08);

    pointer-events: none;
}


.nx-application-page .nx-application-header-main {
    position: relative;
    z-index: 1;

    min-width: 0;
}


.nx-application-page .nx-application-kicker {
    display: flex;

    align-items: center;
    gap: 8px;

    margin-bottom: 11px;

    color: #b9c9d6;

    font-size: 10px;
    font-weight: 800;

    letter-spacing: 1.6px;
}


.nx-application-page .nx-kicker-dot {
    width: 7px;
    height: 7px;

    border-radius: 50%;

    background: #ff6b5b;

    box-shadow:
        0 0 0 4px rgba(255, 107, 91, 0.12);
}


.nx-application-page .nx-application-header h1 {
    margin: 0;

    color: #ffffff;

    font-size: 30px;
    line-height: 1.2;

    font-weight: 750;

    letter-spacing: -0.5px;
}


.nx-application-page .nx-application-header p {
    margin: 9px 0 0;

    color: #c9d5df;

    font-size: 14px;
    line-height: 1.5;
}


.nx-application-page .nx-header-divider {
    margin: 0 7px;

    color: #71889b;
}


/* =========================================================
   HEADER STATUS
   ========================================================= */

.nx-application-page .nx-application-header-status {
    flex: 0 0 auto;

    position: relative;
    z-index: 1;

    min-width: 145px;

    display: inline-flex;

    align-items: center;
    justify-content: center;

    gap: 9px;

    padding: 11px 17px;

    border-radius: 999px;

    background: rgba(255, 255, 255, 0.10);

    border: 1px solid rgba(255, 255, 255, 0.13);

    color: #ffffff;

    font-size: 12px;
    font-weight: 700;

    backdrop-filter: blur(6px);
}


.nx-application-page .nx-status-dot {
    width: 8px;
    height: 8px;

    border-radius: 50%;

    background: #c7d3dc;
}


/* Status states */

.nx-application-page
.nx-application-header-status.applied
.nx-status-dot {
    background: #8da5b7;
}


.nx-application-page
.nx-application-header-status.shortlisted
.nx-status-dot {
    background: #f1c76b;
}


.nx-application-page
.nx-application-header-status.interview
.nx-status-dot {
    background: #91b8d6;
}


.nx-application-page
.nx-application-header-status.selected
.nx-status-dot {
    background: #86c7a2;
}


.nx-application-page
.nx-application-header-status.offered
.nx-status-dot {
    background: #8fd0b0;
}


.nx-application-page
.nx-application-header-status.rejected
.nx-status-dot {
    background: #ef9b91;
}


/* =========================================================
   SUMMARY
   ========================================================= */

.nx-application-page .nx-application-summary {
    display: grid;

    grid-template-columns:
        repeat(4, minmax(0, 1fr));

    margin-top: 18px;

    background: #ffffff;

    border: 1px solid #e3e9ef;

    border-radius: 15px;

    box-shadow:
        0 5px 18px rgba(23, 43, 63, 0.045);

    overflow: hidden;
}


.nx-application-page .nx-summary-item {
    min-height: 95px;

    padding: 21px 24px;

    display: flex;
    flex-direction: column;

    justify-content: center;

    border-right: 1px solid #e8edf2;
}


.nx-application-page .nx-summary-item:last-child {
    border-right: 0;
}


.nx-application-page .nx-summary-label {
    margin-bottom: 8px;

    color: #7a8998;

    font-size: 10px;
    font-weight: 800;

    letter-spacing: 1px;
    text-transform: uppercase;
}


.nx-application-page .nx-summary-value {
    color: #20384d;

    font-size: 15px;
    font-weight: 700;

    line-height: 1.4;
}


/* =========================================================
   SECTIONS
   ========================================================= */

.nx-application-page .nx-application-section {
    margin-top: 38px;
}


.nx-application-page .nx-section-heading {
    display: flex;

    align-items: center;

    gap: 13px;

    margin-bottom: 17px;
}


.nx-application-page .nx-section-heading-icon {
    width: 38px;
    height: 38px;

    flex: 0 0 38px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 10px;

    background: #edf3f7;

    color: #17334b;

    font-size: 15px;
}


.nx-application-page .nx-section-heading h2 {
    margin: 0;

    color: #17334b;

    font-size: 18px;
    font-weight: 750;

    line-height: 1.3;
}


.nx-application-page .nx-section-heading p {
    margin: 4px 0 0;

    color: #788897;

    font-size: 12px;
    line-height: 1.4;
}


/* =========================================================
   INFORMATION CARD
   ========================================================= */

.nx-application-page .nx-information-card {
    background: #ffffff;

    border: 1px solid #e3e9ef;

    border-radius: 15px;

    box-shadow:
        0 5px 18px rgba(23, 43, 63, 0.045);

    overflow: hidden;
}


.nx-application-page .nx-information-grid {
    display: grid;

    grid-template-columns:
        repeat(3, minmax(0, 1fr));
}


.nx-application-page .nx-information-field {
    min-height: 105px;

    padding: 22px 24px;

    display: flex;
    flex-direction: column;

    justify-content: center;

    border-right: 1px solid #edf0f3;
    border-bottom: 1px solid #edf0f3;
}


.nx-application-page
.nx-information-field:nth-child(3n) {
    border-right: 0;
}


.nx-application-page
.nx-information-field:nth-last-child(-n + 3) {
    border-bottom: 0;
}


.nx-application-page .nx-information-label {
    margin-bottom: 9px;

    color: #7c8c9b;

    font-size: 10px;
    font-weight: 800;

    letter-spacing: 0.9px;
    text-transform: uppercase;
}


.nx-application-page .nx-information-value {
    color: #263f54;

    font-size: 14px;
    font-weight: 650;

    line-height: 1.45;
}


/* =========================================================
   ELIGIBILITY
   ========================================================= */

.nx-application-page .nx-eligibility {
    display: inline-flex;

    align-items: center;

    width: fit-content;

    padding: 5px 10px;

    border-radius: 6px;

    font-size: 11px;
    font-weight: 750;
}


.nx-application-page .nx-eligibility.eligible {
    background: #edf7f1;
    color: #28744d;
}


.nx-application-page .nx-eligibility.not-eligible {
    background: #fff1ef;
    color: #b84d42;
}


/* =========================================================
   STATUS TEXT
   ========================================================= */

.nx-application-page .nx-status-text {
    font-weight: 750;
}


.nx-application-page .nx-status-text.applied {
    color: #536b7e;
}


.nx-application-page .nx-status-text.shortlisted {
    color: #9a721b;
}


.nx-application-page .nx-status-text.interview {
    color: #43799d;
}


.nx-application-page .nx-status-text.selected {
    color: #28744d;
}


.nx-application-page .nx-status-text.offered {
    color: #28744d;
}


.nx-application-page .nx-status-text.rejected {
    color: #b84d42;
}


/* =========================================================
   APPLICATION JOURNEY CARD
   ========================================================= */

.nx-application-page .nx-journey-card {
    position: relative;

    padding: 30px 32px 28px;

    background: #ffffff;

    border: 1px solid #e3e9ef;

    border-radius: 15px;

    box-shadow:
        0 5px 18px rgba(23, 43, 63, 0.045);
}


/* =========================================================
   JOURNEY LINE
   ========================================================= */

.nx-application-page .nx-journey-line {
    position: absolute;

    top: 51px;

    left: 10%;

    right: 10%;

    height: 2px;

    background: #e3e9ef;

    z-index: 0;
}


/* =========================================================
   JOURNEY STEPS
   ========================================================= */

.nx-application-page .nx-journey-card {
    display: flex;

    align-items: flex-start;

    justify-content: space-between;

    gap: 12px;

    flex-wrap: wrap;
}


.nx-application-page .nx-journey-step {
    flex: 1 1 140px;

    min-width: 125px;

    position: relative;

    z-index: 1;

    display: flex;
    flex-direction: column;

    align-items: center;

    text-align: center;
}


/* =========================================================
   JOURNEY MARKER
   ========================================================= */

.nx-application-page .nx-journey-marker {
    width: 42px;
    height: 42px;

    display: flex;
    align-items: center;
    justify-content: center;

    margin-bottom: 12px;

    border-radius: 50%;

    background: #ffffff;

    border: 2px solid #dce4ea;

    color: #9aa8b4;

    font-size: 12px;
    font-weight: 800;

    transition:
        background 0.2s ease,
        border-color 0.2s ease,
        color 0.2s ease;
}


/* =========================================================
   JOURNEY CONTENT
   ========================================================= */

.nx-application-page .nx-journey-content {
    display: flex;

    flex-direction: column;

    gap: 4px;
}


.nx-application-page .nx-journey-content strong {
    color: #8796a3;

    font-size: 12px;
    font-weight: 750;
}


.nx-application-page .nx-journey-content span {
    color: #a0adb8;

    font-size: 10px;

    line-height: 1.4;
}


/* =========================================================
   COMPLETED
   ========================================================= */

.nx-application-page
.nx-journey-step.journey-completed
.nx-journey-marker {
    background: #17334b;

    border-color: #17334b;

    color: #ffffff;
}


.nx-application-page
.nx-journey-step.journey-completed
.nx-journey-content strong {
    color: #29465c;
}


.nx-application-page
.nx-journey-step.journey-completed
.nx-journey-content span {
    color: #718391;
}


/* =========================================================
   CURRENT
   ========================================================= */

.nx-application-page
.nx-journey-step.journey-current
.nx-journey-marker {
    background: #ff6b5b;

    border-color: #ff6b5b;

    color: #ffffff;

    box-shadow:
        0 0 0 5px rgba(255, 107, 91, 0.12);
}


.nx-application-page
.nx-journey-step.journey-current
.nx-journey-content strong {
    color: #17334b;
}


.nx-application-page
.nx-journey-step.journey-current
.nx-journey-content span {
    color: #657887;
}


/* =========================================================
   REJECTED JOURNEY
   ========================================================= */

.nx-application-page
.nx-journey-step.journey-rejected
.nx-journey-marker {
    background: #fff1ef;

    border-color: #e59a91;

    color: #b84d42;
}


.nx-application-page
.nx-journey-step.journey-rejected
.nx-journey-content strong {
    color: #b84d42;
}


/* =========================================================
   REJECTED MESSAGE
   ========================================================= */

.nx-application-page .nx-rejected-message {
    flex: 0 0 100%;

    display: flex;

    align-items: center;

    gap: 12px;

    margin-top: 22px;

    padding: 14px 16px;

    background: #fff7f5;

    border: 1px solid #f1d6d1;

    border-radius: 10px;
}


.nx-application-page .nx-rejected-icon {
    width: 28px;
    height: 28px;

    flex: 0 0 28px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: #f9ddd9;

    color: #b84d42;

    font-size: 12px;
    font-weight: 800;
}


.nx-application-page .nx-rejected-message strong {
    display: block;

    margin-bottom: 3px;

    color: #9e4037;

    font-size: 12px;
}


.nx-application-page .nx-rejected-message p {
    margin: 0;

    color: #8a6d68;

    font-size: 11px;
    line-height: 1.5;
}


/* =========================================================
   PLACEMENT DRIVE CARD
   ========================================================= */

.nx-application-page .nx-drive-card {
    display: grid;

    grid-template-columns:
        minmax(240px, 0.75fr)
        minmax(0, 1.5fr);

    background: #ffffff;

    border: 1px solid #e3e9ef;

    border-radius: 15px;

    box-shadow:
        0 5px 18px rgba(23, 43, 63, 0.045);

    overflow: hidden;
}


/* =========================================================
   COMPANY BLOCK
   ========================================================= */

.nx-application-page .nx-company-block {
    min-height: 190px;

    padding: 30px;

    display: flex;

    align-items: center;

    gap: 18px;

    background: #f8fafb;

    border-right: 1px solid #e7edf2;
}


.nx-application-page .nx-company-avatar {
    width: 58px;
    height: 58px;

    flex: 0 0 58px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 14px;

    background: #17334b;

    color: #ffffff;

    font-size: 21px;
    font-weight: 800;

    box-shadow:
        0 6px 14px rgba(23, 51, 75, 0.14);
}


.nx-application-page .nx-company-label {
    display: block;

    margin-bottom: 5px;

    color: #8a99a6;

    font-size: 9px;
    font-weight: 800;

    letter-spacing: 1.2px;
}


.nx-application-page .nx-company-block h3 {
    margin: 0;

    color: #17334b;

    font-size: 19px;
    font-weight: 750;

    line-height: 1.3;
}


/* =========================================================
   DRIVE INFORMATION
   ========================================================= */

.nx-application-page .nx-drive-information {
    display: grid;

    grid-template-columns:
        repeat(2, minmax(0, 1fr));

    padding: 10px 0;
}


.nx-application-page .nx-drive-field {
    min-height: 82px;

    padding: 18px 24px;

    display: flex;
    flex-direction: column;

    justify-content: center;

    border-bottom: 1px solid #edf0f3;
}


.nx-application-page
.nx-drive-field:nth-child(odd) {
    border-right: 1px solid #edf0f3;
}


.nx-application-page
.nx-drive-field:nth-last-child(-n + 2) {
    border-bottom: 0;
}


.nx-application-page .nx-drive-field span {
    margin-bottom: 7px;

    color: #82919e;

    font-size: 9px;
    font-weight: 800;

    letter-spacing: 0.9px;

    text-transform: uppercase;
}


.nx-application-page .nx-drive-field strong {
    color: #294258;

    font-size: 13px;
    font-weight: 700;

    line-height: 1.4;
}


/* =========================================================
   INFORMATION NOTE
   ========================================================= */

.nx-application-page .nx-application-note {
    margin-top: 30px;

    display: flex;

    align-items: flex-start;

    gap: 13px;

    padding: 17px 19px;

    background: #eef4f7;

    border: 1px solid #dce7ed;

    border-radius: 11px;
}


.nx-application-page .nx-note-icon {
    width: 26px;
    height: 26px;

    flex: 0 0 26px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: #dbe7ed;

    color: #315269;

    font-size: 12px;
    font-weight: 800;
}


.nx-application-page .nx-application-note strong {
    display: block;

    margin-bottom: 4px;

    color: #29465c;

    font-size: 12px;
}


.nx-application-page .nx-application-note p {
    margin: 0;

    color: #687d8d;

    font-size: 11px;

    line-height: 1.6;
}


/* =========================================================
   FOOTER
   ========================================================= */

.nx-application-page .nx-application-footer {
    display: flex;

    justify-content: flex-start;

    padding-top: 25px;
}


.nx-application-page .nx-bottom-back-btn {
    display: inline-flex;

    align-items: center;
    justify-content: center;

    gap: 8px;

    padding: 11px 17px;

    border: 1px solid #d7e0e7;

    border-radius: 8px;

    background: #ffffff;

    color: #425d71;

    font-size: 12px;
    font-weight: 700;

    cursor: pointer;

    transition:
        border-color 0.2s ease,
        background 0.2s ease,
        color 0.2s ease,
        transform 0.2s ease;
}


.nx-application-page .nx-bottom-back-btn:hover {
    border-color: #b9c8d3;

    background: #f8fafb;

    color: #17334b;

    transform: translateY(-1px);
}


/* =========================================================
   RESPONSIVE - LARGE TABLET
   ========================================================= */

@media (max-width: 1100px) {

    .nexora-main.nx-application-page {
        padding: 35px 30px 50px;
    }


    .nx-application-page .nx-application-summary {
        grid-template-columns:
            repeat(2, minmax(0, 1fr));
    }


    .nx-application-page .nx-summary-item {
        border-bottom: 1px solid #e8edf2;
    }


    .nx-application-page
    .nx-summary-item:nth-child(2) {
        border-right: 0;
    }


    .nx-application-page
    .nx-summary-item:nth-child(3),
    .nx-application-page
    .nx-summary-item:nth-child(4) {
        border-bottom: 0;
    }


    .nx-application-page .nx-information-grid {
        grid-template-columns:
            repeat(2, minmax(0, 1fr));
    }


    .nx-application-page
    .nx-information-field:nth-child(3n) {
        border-right: 1px solid #edf0f3;
    }


    .nx-application-page
    .nx-information-field:nth-child(2n) {
        border-right: 0;
    }


    .nx-application-page
    .nx-information-field:nth-last-child(-n + 3) {
        border-bottom: 1px solid #edf0f3;
    }


    .nx-application-page
    .nx-information-field:nth-last-child(-n + 2) {
        border-bottom: 0;
    }


    .nx-application-page .nx-drive-card {
        grid-template-columns: 1fr;
    }


    .nx-application-page .nx-company-block {
        min-height: auto;

        border-right: 0;
        border-bottom: 1px solid #e7edf2;
    }

}


/* =========================================================
   RESPONSIVE - TABLET
   ========================================================= */

@media (max-width: 820px) {

    .nexora-main.nx-application-page {
        padding: 28px 22px 45px;
    }


    .nx-application-page .nx-application-header {
        align-items: flex-start;

        flex-direction: column;

        padding: 28px;
    }


    .nx-application-page
    .nx-application-header-status {
        align-self: flex-start;
    }


    .nx-application-page .nx-journey-card {
        padding: 25px 20px;
    }


    .nx-application-page .nx-journey-line {
        display: none;
    }


    .nx-application-page .nx-journey-step {
        flex: 1 1 30%;
    }

}


/* =========================================================
   RESPONSIVE - MOBILE
   ========================================================= */

@media (max-width: 600px) {

    .nexora-main.nx-application-page {
        padding: 22px 15px 38px;
    }


    .nx-application-page .nx-back-link {
        margin-bottom: 18px;
    }


    .nx-application-page .nx-application-header {
        padding: 24px 21px;

        border-radius: 14px;
    }


    .nx-application-page
    .nx-application-header h1 {
        font-size: 23px;
    }


    .nx-application-page
    .nx-application-header p {
        font-size: 12px;
    }


    .nx-application-page
    .nx-application-header-status {
        min-width: 0;
        width: 100%;
    }


    .nx-application-page .nx-application-summary {
        grid-template-columns: 1fr;

        border-radius: 13px;
    }


    .nx-application-page .nx-summary-item {
        min-height: 82px;

        border-right: 0;

        border-bottom: 1px solid #e8edf2;
    }


    .nx-application-page
    .nx-summary-item:last-child {
        border-bottom: 0;
    }


    .nx-application-page .nx-information-grid {
        grid-template-columns: 1fr;
    }


    .nx-application-page .nx-information-field {
        border-right: 0 !important;
        border-bottom: 1px solid #edf0f3 !important;
    }


    .nx-application-page
    .nx-information-field:last-child {
        border-bottom: 0 !important;
    }


    .nx-application-page .nx-section-heading {
        align-items: flex-start;
    }


    .nx-application-page .nx-section-heading h2 {
        font-size: 16px;
    }


    .nx-application-page .nx-section-heading p {
        font-size: 11px;
    }


    .nx-application-page .nx-journey-card {
        padding: 22px 18px;
    }


    .nx-application-page .nx-journey-step {
        flex: 1 1 100%;

        flex-direction: row;

        align-items: center;

        text-align: left;

        gap: 13px;

        padding: 8px 0;
    }


    .nx-application-page .nx-journey-marker {
        margin-bottom: 0;

        width: 36px;
        height: 36px;

        flex: 0 0 36px;
    }


    .nx-application-page .nx-journey-content {
        flex: 1;
    }


    .nx-application-page .nx-drive-information {
        grid-template-columns: 1fr;
    }


    .nx-application-page .nx-drive-field {
        border-right: 0 !important;
        border-bottom: 1px solid #edf0f3 !important;
    }


    .nx-application-page
    .nx-drive-field:last-child {
        border-bottom: 0 !important;
    }


    .nx-application-page .nx-company-block {
        padding: 23px;
    }


    .nx-application-page .nx-application-note {
        padding: 15px;
    }

}


/* =========================================================
   SMALL MOBILE
   ========================================================= */

@media (max-width: 420px) {

    .nexora-main.nx-application-page {
        padding-left: 11px;
        padding-right: 11px;
    }


    .nx-application-page
    .nx-application-header {
        padding: 21px 17px;
    }


    .nx-application-page
    .nx-application-header h1 {
        font-size: 21px;
    }


    .nx-application-page
    .nx-company-avatar {
        width: 50px;
        height: 50px;

        flex-basis: 50px;

        font-size: 18px;
    }


    .nx-application-page
    .nx-company-block h3 {
        font-size: 17px;
    }

}

sp_widget.script:
(function() {

    data.application = null;
    data.error = '';


    // =====================================================
    // GET APPLICATION SYS_ID
    // =====================================================

    var applicationId =
        $sp.getParameter('sys_id');


    /*
     * If URL parameter is not available,
     * use the value sent from Client Controller.
     */

    if (
        !applicationId &&
        typeof input !== 'undefined' &&
        input &&
        input.applicationId
    ) {

        applicationId =
            input.applicationId;

    }


    // =====================================================
    // VALIDATE APPLICATION ID
    // =====================================================

    if (!applicationId) {

        data.error =
            'Application record was not specified.';

        return;

    }


    // =====================================================
    // LOGGED-IN USER
    // =====================================================

    var userId =
        gs.getUserID();


    if (!userId) {

        data.error =
            'Unable to identify the logged-in user.';

        return;

    }


    // =====================================================
    // FIND STUDENT
    // =====================================================

    var studentGR =
        new GlideRecord(
            'x_2065256_colleg_0_student'
        );


    studentGR.addQuery(
        'user',
        userId
    );

    studentGR.setLimit(1);
    studentGR.query();


    if (!studentGR.next()) {

        data.error =
            'Student profile not found for the logged-in user.';

        return;

    }


    var studentSysId =
        studentGR.getUniqueValue();


    // =====================================================
    // FIND APPLICATION
    // =====================================================

    var applicationGR =
        new GlideRecord(
            'x_2065256_colleg_0_application'
        );


    /*
     * Application must:
     *
     * 1. Match sys_id from URL
     * 2. Belong to logged-in student
     */

    applicationGR.addQuery(
        'sys_id',
        applicationId
    );

    applicationGR.addQuery(
        'student',
        studentSysId
    );

    applicationGR.setLimit(1);
    applicationGR.query();


    if (!applicationGR.next()) {

        data.error =
            'Application not found or you do not have access to this application.';

        return;

    }


    // =====================================================
    // BUILD APPLICATION OBJECT
    // =====================================================

    var result = {};


    /*
     * REAL APPLICATION SYS_ID
     */

    result.sys_id =
        applicationGR.getUniqueValue();


    /*
     * APPLICATION NUMBER
     *
     * Your My Applications script uses
     * application_number.
     */

    if (
        applicationGR.isValidField(
            'application_number'
        )
    ) {

        result.applicationNumber =
            applicationGR.getDisplayValue(
                'application_number'
            );

    }


    /*
     * STUDENT
     */

    result.studentName =
        applicationGR.getDisplayValue(
            'student'
        );


    /*
     * REGISTER NUMBER
     */

    if (
        applicationGR.isValidField(
            'register_number'
        )
    ) {

        result.registerNumber =
            applicationGR.getDisplayValue(
                'register_number'
            );

    }


    /*
     * APPLIED DATE
     */

    result.appliedDate =
        applicationGR.getDisplayValue(
            'applied_date'
        );


    /*
     * ELIGIBILITY
     */

    result.eligibilityStatus =
        applicationGR.getDisplayValue(
            'eligibility_status'
        );


    /*
     * APPLICATION STATUS
     */

    result.status =
        applicationGR.getDisplayValue(
            'status'
        ) || 'Applied';


    // =====================================================
    // DRIVE
    // =====================================================

    var driveSysId =
        applicationGR.getValue(
            'drive'
        );


    result.driveSysId =
        driveSysId;


    if (driveSysId) {

        var driveGR =
            new GlideRecord(
                'x_2065256_colleg_0_placement_drive'
            );


        if (
            driveGR.get(
                driveSysId
            )
        ) {


            // =================================================
            // COMPANY
            // =================================================

            if (
                driveGR.isValidField(
                    'company'
                )
            ) {

                result.company =
                    driveGR.getDisplayValue(
                        'company'
                    );

            }


            // =================================================
            // DRIVE NAME
            // =================================================

            if (
                driveGR.isValidField(
                    'drive_name'
                )
            ) {

                result.driveName =
                    driveGR.getDisplayValue(
                        'drive_name'
                    );

            }


            // =================================================
            // JOB ROLE
            // =================================================

            if (
                driveGR.isValidField(
                    'job_role'
                )
            ) {

                result.jobRole =
                    driveGR.getDisplayValue(
                        'job_role'
                    );

            }


            // =================================================
            // PACKAGE
            // =================================================

            if (
                driveGR.isValidField(
                    'package'
                )
            ) {

                result.package =
                    driveGR.getDisplayValue(
                        'package'
                    );

            }


            // =================================================
            // DRIVE DATE
            // =================================================

            if (
                driveGR.isValidField(
                    'drive_date'
                )
            ) {

                result.driveDate =
                    driveGR.getDisplayValue(
                        'drive_date'
                    );

            }

        }

    }


    // =====================================================
    // DEFAULT VALUES
    // =====================================================

    if (!result.applicationNumber) {

        result.applicationNumber =
            '—';

    }


    if (!result.studentName) {

        result.studentName =
            '—';

    }


    if (!result.registerNumber) {

        result.registerNumber =
            '—';

    }


    if (!result.appliedDate) {

        result.appliedDate =
            '—';

    }


    if (!result.eligibilityStatus) {

        result.eligibilityStatus =
            'Pending';

    }


    if (!result.status) {

        result.status =
            'Applied';

    }


    if (!result.company) {

        result.company =
            'Company';

    }


    if (!result.driveName) {

        result.driveName =
            'Placement Drive';

    }


    if (!result.jobRole) {

        result.jobRole =
            '—';

    }


    if (!result.package) {

        result.package =
            '—';

    }


    if (!result.driveDate) {

        result.driveDate =
            '—';

    }


    // =====================================================
    // COMPANY INITIAL
    // =====================================================

    result.companyInitial =
        'C';


    if (
        result.company &&
        result.company !== 'Company'
    ) {

        result.companyInitial =
            String(
                result.company
            )
            .trim()
            .substring(
                0,
                1
            )
            .toUpperCase();

    }


    // =====================================================
    // RETURN APPLICATION
    // =====================================================

    data.application =
        result;

})();
